"""Tiny CSV summary. Usage: python stats.py FILE COLUMN"""
import sys


def summarize(path, column):
    with open(path) as f:
        lines = f.read().splitlines()
    header = lines[0].split(",")
    rows = []
    for line in lines[1:]:
        if line.strip() == "":
            continue
        parts = line.split(",")
        if len(parts) != len(header):
            continue
        row = dict(zip(header, parts))
        rows.append(row)
    if not rows:
        return {"rows": 0}
    # Compute mean and max
    scores = []
    for row in rows:
        try:
            scores.append(float(row["score"]))
        except (KeyError, ValueError):
            continue
    mean_val = sum(scores) / len(scores) if scores else None
    max_val = max(scores) if scores else None
    return {
        "rows": len(rows),
        "mean": mean_val,
        "max": max_val,
    }


def main(argv):
    if len(argv) != 2:
        print(__doc__)
        return 1
    s = summarize(argv[0], argv[1])
    for k, v in s.items():
        print(f"{k} {v}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

